import React from "react";

// Images (mets les bons chemins)
import AccelLogo from "assets/img/accel_logo.png";
import IconLink from "assets/img/link.png";
import IconPhone from "assets/img/phone.png";
import IconMail from "assets/img/mail.png";
import IconGlobe from "assets/img/globe.png";

// Icônes réseaux (version orange comme sur la maquette)
import IconFb from "assets/img/facebook_orange.png";
import IconLn from "assets/img/linkedin_orange.png";
import IconYt from "assets/img/youtube_orange.png";

export default function Footer() {
  return (
    <footer className="bg-[#1e204a] text-white">
      {/* Bande principale */}
      <div className="max-w-[1280px] mx-auto px-6 lg:px-12 py-16 lg:py-20 grid grid-cols-1 md:grid-cols-3 gap-12 lg:gap-20">
        {/* Col 1 : Powered By */}
        <div className="flex flex-col items-start">
          <h3 className="text-[34px] leading-none font-extrabold mb-10 tracking-wide">
            Powered By
          </h3>
          <img
            src={AccelLogo}
            alt="Accel"
            className="h-20 w-20 object-contain"
          />
        </div>

        {/* Col 2 : Liens utiles + réseaux */}
        <div className="flex flex-col items-start">
          <h3 className="text-[28px] font-semibold mb-8 tracking-wide">
            Liens utiles
          </h3>

          <ul className="space-y-7">
            <li className="flex items-center gap-5">
              <img src={IconLink} alt="" className="h-7 w-7 opacity-90" />
              <a
                href="#"
                className="text-[22px] leading-tight hover:underline focus:underline"
              >
                Red Hat Enterprise Linux
              </a>
            </li>
            <li className="flex items-center gap-5">
              <img src={IconLink} alt="" className="h-7 w-7 opacity-90" />
              <a
                href="#"
                className="text-[22px] leading-tight hover:underline focus:underline"
              >
                Openshift AI
              </a>
            </li>
            <li className="flex items-center gap-5">
              <img src={IconLink} alt="" className="h-7 w-7 opacity-90" />
              <a
                href="#"
                className="text-[22px] leading-tight hover:underline focus:underline"
              >
                Heritage Cloud
              </a>
            </li>
          </ul>

          {/* Réseaux sociaux */}
          <div className="mt-16 flex items-center gap-10">
            <a
              href="#"
              aria-label="Facebook"
              className="transition-transform hover:scale-110 focus:scale-110"
            >
              <img src={IconFb} alt="Facebook" className="h-8 w-8" />
            </a>
            <a
              href="#"
              aria-label="LinkedIn"
              className="transition-transform hover:scale-110 focus:scale-110"
            >
              <img src={IconLn} alt="LinkedIn" className="h-8 w-8" />
            </a>
            <a
              href="#"
              aria-label="YouTube"
              className="transition-transform hover:scale-110 focus:scale-110"
            >
              <img src={IconYt} alt="YouTube" className="h-8 w-8" />
            </a>
          </div>
        </div>

        {/* Col 3 : Contacts */}
        <div className="flex flex-col items-start">
          <h3 className="text-[28px] font-semibold mb-8 tracking-wide">
            Contacts
          </h3>
          <ul className="space-y-7">
            <li className="flex items-center gap-8">
              <img src={IconPhone} alt="" className="h-7 w-7 opacity-90" />
              <span className="text-[22px] leading-tight">33.000.00.00</span>
            </li>
            <li className="flex items-center gap-8">
              <img src={IconMail} alt="" className="h-7 w-7 opacity-90" />
              <a
                href="mailto:xxx@example.com"
                className="text-[22px] leading-tight hover:underline focus:underline"
              >
                xxx@example.com
              </a>
            </li>
            <li className="flex items-center gap-8">
              <img src={IconGlobe} alt="" className="h-7 w-7 opacity-90" />
              <a
                href="https://www.example.com"
                className="text-[22px] leading-tight hover:underline focus:underline"
                target="_blank"
                rel="noreferrer"
              >
                www.example.com
              </a>
            </li>
          </ul>
        </div>
      </div>

      {/* Ligne inférieure */}
      <div className="border-t border-white/20">
        <div className="max-w-[1280px] mx-auto px-6 lg:px-12 py-4">
          {/* Optionnel : copyright */}
          {/* <p className="text-sm text-white/70">© 2025 Accel Tech — Tous droits réservés.</p> */}
        </div>
      </div>
    </footer>
  );
}
